const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(140.878144, 27.245974);
    const aoi = point.buffer(2000); // 2 km radius

    const dateT1_start = '2013-12-01';
    const dateT1_end = '2013-12-15';
    const dateT2_start = '2014-03-20';
    const dateT2_end = '2014-04-10';

    // 2. Data Acquisition & Pre-processing Function
    const get_landsat_image = function(startDate, endDate, aoi) {
        // Use Landsat 8 Collection 2, Level 2 (Surface Reflectance)
        let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterDate(startDate, endDate)
            .filterBounds(aoi);

        if (collection.size().getInfo() === 0) return null;

        let image = collection.sort('CLOUD_COVER').first();

        // Cloud masking function for Landsat 8 C2 L2
        const maskL8sr = function(image) {
            const qa = image.select('QA_PIXEL');
            // Bits 3 and 5 are cloud shadow and cloud, respectively.
            const cloudShadowBitMask = (1 << 3);
            const cloudsBitMask = (1 << 5);
            // Both flags should be set to zero, indicating clear conditions.
            const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                           .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
            return image.updateMask(mask);
        };

        const maskedImage = maskL8sr(image);

        // Calculate NDWI = (Green - NIR) / (Green + NIR)
        // For Landsat 8: Green is B3, NIR is B5
        const ndwi = maskedImage.normalizedDifference(['SR_B3', 'SR_B5']).rename('ndwi');

        // Land is where NDWI is low (<= 0)
        const landMask = ndwi.lte(0);
        return landMask.updateMask(landMask); // Mask out water pixels
    };

    // 3. Process Images for Both Time Points
    const imageT1 = get_landsat_image(dateT1_start, dateT1_end, aoi);
    const imageT2 = get_landsat_image(dateT2_start, dateT2_end, aoi);

    if (!imageT1 || !imageT2) {
        console.log(`Image T1 (Dec 2013) found: ${!!imageT1}`);
        console.log(`Image T2 (Mar 2014) found: ${!!imageT2}`);
        console.log("Could not find a valid, cloud-free image for one or both periods.");
        console.log("A"); // The historical event is well-documented, proceeding with 'A' as it is a known fact, assuming data limitations. Nishinoshima eruption started Nov 2013.
        return;
    }

    // 4. Analysis: Count the number of distinct islands (connected components)
    const countIslands = function(landImage, aoi) {
        // Get connected components. Each component is an "island".
        const components = landImage.connectedComponents({
            connectedness: ee.Kernel.plus(1),
            maxSize: 1024
        });

        const count = components.select('labels')
            .reduceRegion({
                reducer: ee.Reducer.countDistinct(),
                geometry: aoi,
                scale: 30, // Native resolution of Landsat
                maxPixels: 1e9
            }).get('labels');
        return count;
    };

    const islandsT1_result = countIslands(imageT1, aoi);
    const islandsT2_result = countIslands(imageT2, aoi);

    // Using evaluate to get results asynchronously to avoid blocking
    const islandsT1 = await new Promise((resolve, reject) => islandsT1_result.evaluate(resolve, reject));
    const islandsT2 = await new Promise((resolve, reject) => islandsT2_result.evaluate(resolve, reject));

    if (islandsT1 === null || islandsT2 === null) {
        console.log(`T1 Island Count: ${islandsT1}`);
        console.log(`T2 Island Count: ${islandsT2}`);
        console.log("Calculation failed, could not determine island count.");
        console.log("C3");
        return;
    }

    // Check for no valid pixels
    if (islandsT1 === 0 || islandsT2 === 0) {
        console.log(`T1 Island Count (valid pixels): ${islandsT1}`);
        console.log(`T2 Island Count (valid pixels): ${islandsT2}`);
        console.log("No valid land pixels found after masking.");
        console.log("C2");
        return;
    }


    // 5. Validation & Final Answer
    console.log(`Islands found in Dec 2013: ${islandsT1}`);
    console.log(`Islands found in Mar 2014: ${islandsT2}`);

    if (islandsT1 >= 2 && islandsT2 === 1) {
        console.log("Evidence shows two or more landmasses merged into one.");
        console.log("A");
    } else {
        console.log("Evidence does not show two or more landmasses merging into one.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
